#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> adj(n + 1);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back((int)e[1]);
        adj[e[1]].push_back((int)e[0]);
    }
    vector<char> seen(n + 1, 0);
    int count = 0;
    for (int start = 1; start <= n; start++) {
        if (seen[start]) continue;
        count++;
        seen[start] = 1;
        vector<int> queue = {start};
        for (size_t i = 0; i < queue.size(); i++) {
            for (int w : adj[queue[i]]) {
                if (!seen[w]) {
                    seen[w] = 1;
                    queue.push_back(w);
                }
            }
        }
    }
    cout << count << "\n";

    return 0;
}

